import{_ as e}from"./chunks/icon.B7gRmRZx.js";import{_ as o,a}from"./chunks/block-menu.Dr9I8l8O.js";import{_ as s,o as r,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"Logic Studio","description":"First public test release of the visual function-block editor for Home Assistant.","frontmatter":{"title":"Logic Studio","description":"First public test release of the visual function-block editor for Home Assistant."},"headers":[],"relativePath":"en/projects/logic-studio/index.md","filePath":"en/projects/logic-studio/index.md","lastUpdated":1794146905000}'),d={name:"en/projects/logic-studio/index.md"};function l(c,t,p,u,g,h){return r(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="logic-studio" tabindex="-1"><img class="package-icon" src="'+e+'" width="40" height="40" alt=""> Logic Studio <a class="header-anchor" href="#logic-studio" aria-label="Permalink to &quot;&lt;img class=&quot;package-icon&quot; src=&quot;/images/logic-studio/icon.svg&quot; width=&quot;40&quot; height=&quot;40&quot; alt=&quot;&quot;&gt; Logic Studio&quot;">​</a></h1><p><strong>0.1.6 – first public test release, 8 November 2026.</strong> Logic Studio is a standalone HA app for visual function-block plans, independent of Grafik Visual Studio and Blocks for HA. The editor currently uses <strong>German</strong>; this guide is available in <strong>DE/EN/FR</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Test release</p><p>Install on a test system first and create a full backup beforehand. Native detail properties currently use JSON. The app does not write automations/scripts back to HA or control devices. Review and install generated output yourself.</p></div><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/logic-studio-v0.1.6" target="_blank" rel="noreferrer">GitHub test release and ZIP</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/logic_studio" target="_blank" rel="noreferrer">Source in the shared repository</a></p><h2 id="test-installation-from-github" tabindex="-1">Test installation from GitHub <a class="header-anchor" href="#test-installation-from-github" aria-label="Permalink to &quot;Test installation from GitHub&quot;">​</a></h2><p><a href="https://my.home-assistant.io/redirect/supervisor_add_addon_repository/?repository_url=https%3A%2F%2Fgithub.com%2Frockbaer2007%2Fugso-ha-mqtt-addons" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/supervisor_add_addon_repository.svg" alt="Add repository to Home Assistant"></a></p><ol><li>Under <strong>Settings → Apps → App store → Repositories</strong>, add the URL below. If “UGSo HA Apps” is already configured, check for updates instead.</li><li>Select and install <strong>UGSo Logic Studio</strong>. Enable advanced mode in your HA profile if experimental apps are hidden.</li><li>Start it and open its web UI. Supports <strong>HA OS/Supervised</strong>, <strong>amd64 and aarch64</strong>. The first container build may take several minutes. This is not a HACS/Marketplace frontend package.</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Keep an existing local test installation:</strong> GitHub and local apps have different repository IDs and separate data. Export your old plan using <strong>Projekt</strong> as JSON, then use <strong>Öffnen</strong> in the GitHub app. There is no automatic migration or uninstall. Each app retains its project and palette settings under <code>/data</code>.</p><h2 id="two-kinds-of-plan" tabindex="-1">Two kinds of plan <a class="header-anchor" href="#two-kinds-of-plan" aria-label="Permalink to &quot;Two kinds of plan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plan</th><th>Purpose and output</th></tr></thead><tbody><tr><td>Dataflow</td><td>Typed inputs/outputs, logic, math, selection, latches, edges, timers and counters. 33 implemented types; other reference types are marked templates. Export HA automation YAML, HA script YAML or a JavaScript function with a host interface.</td></tr><tr><td>Native HA flow</td><td>Import automations, scripts and blueprints as nested blocks. 53 additional HA types cover triggers, conditions, branches, loops, waits, variables and blueprint inputs. Export native HA YAML only.</td></tr></tbody></table><p>Dataflow simulation uses demo/snapshot values. Persistent blocks need the documented HA text helpers or a JavaScript memory host. Native HA flows are neither executed in the editor nor automatically translated to JavaScript. The JavaScript output is not an ioBroker script.</p><h2 id="import-and-editing" tabindex="-1">Import and editing <a class="header-anchor" href="#import-and-editing" aria-label="Permalink to &quot;Import and editing&quot;">​</a></h2><p>Open <strong>HA importieren</strong>, choose automations/scripts/blueprints, and use <strong>Aus HA einlesen</strong>, a YAML/JSON file or pasted text. Select an entry, review its preview, then choose <strong>Import übernehmen</strong>. Save your existing plan as JSON first; project and source-file backups are also created.</p><p>The HA configuration mount is <strong>read-only</strong>. The app reads <code>automations.yaml</code>, <code>scripts.yaml</code> and blueprint files. Before parsing, sources are copied to <code>/data/ha-source-backups/&lt;timestamp&gt;/</code> using their original names. <code>secrets.yaml</code> is not opened; <code>!secret</code> and <code>!include</code> remain unresolved. Import referenced include files manually.</p><p>Orange <strong>FLOW</strong> wires represent execution order and branches: branch output → <strong>DO</strong>, then <strong>NEXT → DO</strong>. Yellow <strong>VALUE/REF</strong> wires show blueprint parameters and their <code>!input</code> usage. Properties contain HA configuration and branch paths as JSON. Parameter/field keys must be unique. Unknown sections remain <strong>YAML_ORIGINAL</strong>; missing wires can block export.</p><p><img src="'+o+'" alt="Import preview of existing HA blueprints"></p><p>Each block’s <strong>⋮ menu</strong> offers <strong>Eigenschaften</strong> (properties), <strong>Duplizieren</strong> (duplicate) and <strong>Löschen</strong> (delete). Duplication copies properties without wires. Deletion removes associated wires; undo restores them. Search, favorites and recently used blocks help navigation.</p><p><img src="'+a+'" alt="Per-block three-dot menu"></p><h2 id="validation-and-limits" tabindex="-1">Validation and limits <a class="header-anchor" href="#validation-and-limits" aria-label="Permalink to &quot;Validation and limits&quot;">​</a></h2><p>The <strong>0.1.5</strong> functional baseline was tested on <strong>.193 / HA Core 2026.10.4</strong>: actual blueprint import, automation/script/blueprint fixtures, semantically identical YAML exports and menu actions. <strong>0.1.6</strong> is its first public packaging. 22 Node and eight Python tests cover export, persistence, nested flows and safe source import; GitHub checks also build the container.</p><p>The editor does not provide complete HA semantic validation: verify targets, templates and selectors in HA. Comments, YAML anchors and formatting are not reconstructed. Import limits: <strong>1 MB, 200 blocks, 500 wires</strong>, bounded nesting and up to 250 blueprint files in standard folders. Controllers, calendar and custom subplans partly remain templates.</p><p>For local tests, extract the entire release ZIP, install Python 3.10+ and <code>requirements.txt</code>, then run <strong>Start-Demo.cmd</strong> on Windows. <code>http://127.0.0.1:4180/</code> shows demo entities without connecting to HA. The ZIP also contains <code>addon/logic_studio/</code> for local app installations.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/issues" target="_blank" rel="noreferrer">Report issues on GitHub</a> with versions, architecture and a minimal anonymized example. Do not publish credentials, personal automations or full backups. Further guides and the test report are included. MIT license; extracted block metadata attribution is in <code>THIRD-PARTY.txt</code>.</p>',24)])])}const v=s(d,[["render",l]]);export{k as __pageData,v as default};
